public class Solution {
    public static String[] separate_paren_groups(String a0) {
        List<String> result = new ArrayList<>();
        StringBuilder currentStringBuilder = new StringBuilder();
        int currentDepth = 0;

        char[] chars = a0.toCharArray();
        Stack<Character> stack = new Stack<>();

        for (char c : chars) {
            if (c == '(') {
                currentDepth++;
                stack.push(c);
            } else if (c == ')') {
                currentDepth--;
                if (currentDepth == 0) {
                    result.add(currentStringBuilder.toString());
                    currentStringBuilder.setLength(0);
                    while (!stack.isEmpty() && stack.peek() != '(') {
                        currentStringBuilder.append(stack.pop());
                    }
                    if (stack.isEmpty()) {
                        stack.push(c);
                    }
                } else {
                    currentStringBuilder.append(c);
                }
            } else {
                currentStringBuilder.append(c);
            }
        }

        if (!currentStringBuilder.toString().isEmpty()) {
            result.add(currentStringBuilder.toString());
        }

        String[] answer = new String[result.size()];
        return result.toArray(answer);
    }
}

