public class Solution {
    private static final String REGEX = "\\s*(\\([^()]++(?:(?=(?:[^)(]*(?(?![^\]])*[^()])*)|(?<![^()])(?=[^()]))*)*?)\\s*";

    public static long[] parse_nested_parens(String a0) {
        Deque<Integer> stack = new ArrayDeque<>();
        List<Long> result = IntStream.of(a0.split(REGEX)).mapToObj(x -> {
            if (x == null || x.isEmpty()) return 0L;
            int depth = 0;
            for (char c : x.toCharArray()) {
