                else if (c == ')') depth--;
                if (depth < 0) throw new RuntimeException("Invalid input: " + a0);
            }
            return Long.valueOf(depth);
        }).mapToLong(x -> x).toArray();

        while (!stack.isEmpty()) {
            int top = stack.pollLast();
            result[result.length - 1] += top;
        }

        return result;
    }
}

