public class Solution {
    public static String decodeCyclic(String input) {
        List<String> groups = new ArrayList<>();
        int groupSize = 3;
        int index = 0;

        while (index < input.length()) {
            groups.add(input.substring(index, Math.min(index + groupSize, input.length())));
            index += groupSize;
        }

        List<String> decodedGroups = new ArrayList<>();
        for (String group : groups) {
            if (group.length() >= groupSize) {
                String cycledGroup = rotateString(group);
                decodedGroups.add(cycledGroup.substring(1) + cycledGroup.charAt(0));
            } else {
                decodedGroups.add(group);
            }
        }

        return String.join("", decodedGroups);
    }

    private static String rotateString(String str) {
        char firstChar = str.charAt(0);
        return str.substring(1) + firstChar;
    }
}

