public class Solution {
    public static boolean prime_length(String a0) {
        int length = a0.length();
        if (length <= 1) {
            return false;
        }
        for (int i = 2; i * i <= length; i++) {
            if (isDivisibleBy(a0, i)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isDivisibleBy(String s, int divisor) {
        int remainder = s.length() % divisor;
        List<Integer> digits = new ArrayList<>();
        for (int digit : getDigits(s)) {
            digits.add(digit);
        }
        for (int digit : digits) {
            if (digit * divisor >= Integer.MAX_VALUE / divisor || (remainder + digit) % divisor != 0) {
                return false;
            }
        }
        return true;
    }

    private static List<Integer> getDigits(String s) {
        int index = 0;
        int number = Character.isDigit(s.charAt(index)) ? Integer.parseInt(s.substring(index, Math.min(index + 1, s.length()))) : 0;
        List<Integer> digits = new ArrayList<>();
        digits.add(number);
        index += number > 0 ? String.valueOf(number).length() : 1;
        while (index < s.length()) {
            number = Character.isDigit(s.charAt(index)) ? Integer.parseInt(s.substring(index, Math.min(index + 1, s.length()))) : 0;
            digits.add(number);
            index += number > 0 ? String.valueOf(number).length() : 1;
        }
        return digits;
    }
}

