public class Solution {
    public static boolean any_int(double a0, double a1, double a2) {
        if (!isValidInt(a0) || !isValidInt(a1) || !isValidInt(a2)) {
            return false;
        }

        if (isTripleEqual(a0, a1, a2) || isTripleSumEqual(a0, a1, a2) || isTripleDifferenceEqual(a0, a1, a2)) {
            return true;
        }

        return false;
    }

    private static boolean isValidInt(double num) {
        return (int) num == (float) num;
    }

    private static boolean isTripleEqual(double a, double b, double c) {
        return (a == b && b == c) || (b == c && c == a) || (c == a && a == b);
    }

    private static boolean isTripleSumEqual(double a, double b, double c) {
        return (a + b == c) || (a + c == b) || (b + c == a);
    }

    private static boolean isTripleDifferenceEqual(double a, double b, double c) {
        return Math.abs(Math.abs(a - b) - Math.abs(b - c)) <= 0.001 && Math.abs(a - c) <= 0.001;
    }
}

