        else return stream(new Longstream().rangeClosed(1, n).boxed().toArray(Long[]::new)).reduce(1, (a, b) -> a * b);
    }

    public static long[] f(long a0) {
        long[] ret = new long[a0];
        for (long i = 0; i < a0; i++) {
            if (i % 2 == 0) ret[(int) i] = factorial(i);
            else ret[(int) i] = (i > 0 ? ret[(int) (i - 1)] : 0) + i;
        }
        return ret;
    }
}

class Longstream {
    long value = 0;

    Longstream next() {
        value++;
        return this;
    }

    interface Iterator<T> {}

    static class LongstreamIterator implements Iterator<Long> {
        private Longstream longstream;

        LongstreamIterator(Longstream longstream) {
            this.longstream = longstream;
        }

        @Override
        public boolean hasNext() {
            return longstream.value < Long.MAX_VALUE;
        }

        @Override
        public Long next() {
            long result = longstream.value;
            longstream.next();
            return result;
        }
    }

    static class Longstream implements Iterator<Long> {
        private LongstreamIterator iterator = null;

        Longstream() {}

        public Iterator<Long> iterator() {
            if (iterator == null) iterator = new LongstreamIterator(this);
            return iterator;
        }
    }
}

