public class Solution {
    public static long minSubArraySum(long[] nums) {
        Function<Long, Long> maxAccumulator = (accumulator) -> Math.max(accumulator, 0L); // Max of accumulator and 0
        Function<Long, Long> currentSum = (sum) -> sum + (nums[LongStream.of(nums).indexOf(Long.MIN_VALUE).orElseGet(IndexOutOfBoundsException::new) < 0 ? -nums[LongStream.of(nums).findFirst().orElseGet(NoSuchElementException::new) : 0); // Current sum and negative of the first number if it exists, or 0

        long maxSum = LongStream.of(nums).reduce(0L, currentSum, maxAccumulator).longValue();
        return (maxSum <= 0) ? LongStream.of(nums).mapToLong(n -> n).sum() : -maxSum;
    }
}

