public class Solution {
    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    public static boolean valid_date(String a0) {
        try {
            LocalDate date = LocalDate.parse(a0, FORMATTER);
            int monthValue = date.getMonthValue();
            return (monthValue >= 1 && monthValue <= 12)
                    || (monthValue == 2 && isLeapYear(date.getYear()) && dayOfMonthValid(monthValue, date.getDayOfMonth()))
                    || (monthValue % 2 != 0 && dayOfMonthValid(monthValue, date.getDayOfMonth()))
                    || (monthValue == 4 || monthValue == 6 || monthValue == 9 || monthValue == 11
                            && dayOfMonthValid(monthValue, date.getDayOfMonth()));
        } catch (DateTimeParseException e) {
            return false;
        }
    }

    private static boolean isLeapYear(int year) {
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }

    private static boolean dayOfMonthValid(int month, int day) {
        switch (month) {
            case 2:
                return isLeapYear(Integer.parseInt(String.valueOf(day.charAt(0)))) && day > 28 || day <= 29;
            case 1, 3, 5, 7, 8, 10, 12:
                return day > 0 && day <= 31;
            default:
                return day > 0 && day <= 30;
        }
    }
}

