public class Solution {
    private static final int INDEX_OUT_OF_BOUNDS = -1;

    public static long[] minPath(long[][] grid, long k) {
        int n = grid.length;
        long val = Long.MAX_VALUE;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1) {
                    long[] temp = new long[4];
                    int pos = 0;

                    if (i > 0) {
                        ++pos;
                        temp[pos] = grid[i - 1][j];
                    }

                    if (j > 0) {
                        ++pos;
                        temp[pos] = grid[i][j - 1];
                    }

                    if (i < n - 1) {
                        ++pos;
                        temp[pos] = grid[i + 1][j];
                    }

                    if (j < n - 1) {
                        ++pos;
                        temp[pos] = grid[i][j + 1];
                    }

                    val = Math.min(val, stream(temp).mapToLong(l -> l == INDEX_OUT_OF_BOUNDS ? Long.MAX_VALUE : l).sum());
                }
            }
        }

        long[] ans = new long[k];
        for (int i = 0; i < k; ++i) {
            if (i % 2 == 0) {
                ans[i] = 1;
            } else {
                ans[i] = val;
            }
        }

        return ans;
    }
}

