        List<Double> result = new ArrayList<>();
        if (n == 0) {
            result.add(1.0);
        } else {
            result.add(1.0);
            result.add(3.0);
            for (int i = 2; i <= n; i++) {
                if (i % 2 == 0) {
                    result.add((double) i / 2 + 1.0);
                } else {
                    double prevTwo = result.get(i - 2);
                    double prevOne = result.get(i - 1);
                    result.add(prevOne + prevTwo + (i + 3) / 2.0);
                }
            }
        }
        double[] output = new double[result.size()];
        for (int i = 0; i < result.size(); i++) {
            output[i] = result.get(i);
        }
        return output;
    }
}

