public class Solution {
    public static boolean is_nested(String input) {
        List<Integer> openingBrackets = new ArrayList<>();
        List<Integer> closingBrackets = new ArrayList<>();

        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c == '[') {
                openingBrackets.add(i);
            } else {
                closingBrackets.add(i);
            }
        }

        // Reverse the order of closing brackets
        List<Integer> reversedClosingBrackets = new ArrayList<>(closingBrackets);
        Collections.reverse(reversedClosingBrackets);

        int count = 0;
        int index = 0;
        for (int openingIndex : openingBrackets) {
            if (index < reversedClosingBrackets.size() && openingIndex < reversedClosingBrackets.get(index)) {
                count++;
                index++;
            }
        }

        return count >= 2;
    }
}

