public class Solution {
    private static String fixSpaces(String text) {
        StringBuilder newText = new StringBuilder();
        int i = 0, start = 0, end = 0;

        while (i < text.length()) {
            char c = text.charAt(i);
            if (c == ' ') {
                end++;
            } else {
                if (end - start > 2) {
                    newText.append("-");
                } else if (end - start > 0) {
                    newText.append(valueOf(_repeat("_", end - start)));
                    newText.append(c);
                    start = i + 1;
                    end = i + 1;
                } else {
                    newText.append(c);
                    start = i + 1;
                }
            }
            i++;
        }

        if (end - start > 2) {
            newText.append("-");
        } else if (end - start > 0) {
            newText.append(valueOf(_repeat("_", end - start)));
        }

        return newText.toString();
    }

    private static String _repeat(String s, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(s);
        }
        return sb.toString();
    }
}

