import static java.lang.String.CASE_INSENSITIVE_ORDER;

public class Solution {
    public static String Strongest_Extension(String className, String[] extensions) {
        String strongest = extensions[0];
        int maxScore = calculateScore(strongest);
         for (String s : extensions) {
            int score = calculateScore(s);
            if (score > maxScore) {
                strongest = s;
                maxScore = score;
            }
        }
        return className + "." + strongest;
    }

    private static int calculateScore(String extension) {
        int upperCount = 0, lowerCount = 0;
        for (char c : extension.toCharArray()) {
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            }
        }
        return upperCount - lowerCount;
    }
}

