                .mapToObj(Function.identity())
                .mapToLong(i -> i % 2 == 0 ? i : -i) // taking absolute value and negating odd numbers for counting
                .sum() > 0 ? new long[] { LongStream.of(LongStream.ofInt(evenOddCount, 0).mapToLong(i -> i).sum(),
