import java.util.Arrays;

public class Solution {
    private static final String OPERATOR_REGEX = "[+-*/]";
    private static final String FIRST_OPERAND = "\\S+";

    public static long do_algebra(String[] a0, long[] a1) {
        String expression = Arrays.toString(a0)[1, a0.length-1]
                .replaceAll("\\[|\\]| ", "")
                .replaceAll(OPERATOR_REGEX, m -> " " + m + " ");

        String[] tokens = expression.split(FIRST_OPERAND);
        long result = a1[0];

        for (int i = 0; i < tokens.length - 1; i++) {
            long operand = a1[i+1];
            String operator = tokens[i];
            result = switch (operator) {
                case "+" -> result + operand;
                case "-" -> result - operand;
                case "*" -> result * operand;
                case "/" -> result / operand;
                default -> throw new IllegalArgumentException("Invalid operator: " + operator);
            };
        }

        return result;
    }
}

import java.util.Formatter;
import java.util.Locale;

public class Solution {
    public static String solve(String input) {
        boolean flag = false;
        char[] chars = new char[input.length()];
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isLetter(c)) {
                chars[i] = Character.isUpperCase(c) ? Character.toLowerCase(c) : Character.toUpperCase(c);
                flag = true;
            } else {
                chars[i] = c;
            }
        }

        StringBuilder result = new StringBuilder();
        Formatter formatter = new Formatter(result, Locale.ENGLISH);
        for (char c : chars) {
            formatter.format("%c", c);
        }

        return flag ? result.toString() : new String(new StringBuilder(result.reverse()).reverse().toString());
    }
}

import static java.lang.Math.*; // for min and max

public class Solution {
    public static long[] generate_integers(long a, long b) {
        long lower = Math.max(2L, Math.min(a, b));
        long upper = Math.min(8L, Math.max(a, b));

        long[] result = new long[staticPowerOfTwo((int) (upper - lower + 1))];
        long index = 0;

        for (long i = lower; i <= upper; i++) {
            if (i % 2 == 0) {
                result[index++] = i;
            }
        }

        long[] output = new long[index];
        System.arraycopy(result, 0, output, 0, index);

        return output;
    }

    private static int staticPowerOfTwo(int power) {
        if (power <= 0) {
            throw new IllegalArgumentException("Power must be greater than zero");
        }

        return (int) Math.pow(2, power);
    }
}

